// probes/powerups/retail-placement-physical.mjs
// Generated by probes/powerups/tools/build_physical_placement.mjs from
// probes/powerups/tools/retail_physical_module.template.mjs,
// probes/powerups/data/arc-correspondence.json and
// probes/powerups/data/retail-placement-physical.json. Do not edit by hand.
//
// Browser-importable physically-corresponded retail pickup placement for the
// e1-drive power-up slice.
//
// Contract:
//   import {
//     PHYSICAL_PLACEMENT_SCHEMA, ARC_CORRESPONDENCE, PHYSICAL_PLACEMENT_DATA,
//     physicalPlacementsFor
//   } from './retail-placement-physical.mjs';
//   const set = physicalPlacementsFor('gracia', layout);
//   // layout is the measured layout the page drives:
//   //   { course: { lengthMetres, band|corridor, samples: [{arc,x,z,groundY}, ...] } }
//
// Rule: a pickup is placed at its retail arc mapped through the committed
// measured-arc <-> retail-arc correspondence table. There is no global arc
// fraction. The retail lateral is clamped to the measured band. A pickup whose
// retail arc has no correspondence segment is returned in `unsupported`.
//
// Every placed pickup carries `physicalProjection: true`, the measured arc, the
// retail arc, the mapping residual and a `source` string naming the retail uid,
// the route, the correspondence segment and the rule.

export const PHYSICAL_PLACEMENT_SCHEMA = 'blur.powerups-physical-placement/1';
export const ARC_CORRESPONDENCE_SCHEMA = 'blur.powerups-arc-correspondence/1';

function deepFreeze(value) {
  if (value && typeof value === 'object' && !Object.isFrozen(value)) {
    Object.freeze(value);
    for (const key of Object.keys(value)) deepFreeze(value[key]);
  }
  return value;
}

function fail(message) {
  throw new Error('retail-placement-physical: ' + message);
}

function round6(value) {
  const rounded = Math.round(value * 1e6) / 1e6;
  return Object.is(rounded, -0) ? 0 : rounded;
}

function bandOf(layout) {
  const band = layout?.course?.band?.halfWidthMetres;
  if (Number.isFinite(band) && band > 0) {
    return { halfWidthMetres: band, source: 'course.band.halfWidthMetres' };
  }
  const corridor = layout?.course?.corridor?.halfWidthMetres;
  if (Number.isFinite(corridor) && corridor > 0) {
    return { halfWidthMetres: corridor, source: 'course.corridor.halfWidthMetres' };
  }
  return null;
}

function measuredLengthOf(layout) {
  const length = layout?.course?.lengthMetres;
  if (Number.isFinite(length) && length > 0) return length;
  const samples = layout?.course?.samples;
  if (Array.isArray(samples) && samples.length > 0) {
    const last = samples[samples.length - 1];
    if (Number.isFinite(last?.arc) && last.arc > 0) return last.arc;
  }
  return null;
}

function nearestSample(samples, targetArc) {
  let bestIndex = 0;
  let bestDelta = Math.abs((samples[0].arc ?? 0) - targetArc);
  for (let index = 1; index < samples.length; index++) {
    const delta = Math.abs((samples[index].arc ?? 0) - targetArc);
    if (delta < bestDelta) {
      bestIndex = index;
      bestDelta = delta;
    }
  }
  return { index: bestIndex, sample: samples[bestIndex], delta: bestDelta };
}

function leftNormalAt(samples, index) {
  const a = samples[Math.max(0, index - 1)];
  const b = samples[Math.min(samples.length - 1, index + 1)];
  const tx = (b.x ?? 0) - (a.x ?? 0);
  const tz = (b.z ?? 0) - (a.z ?? 0);
  const length = Math.hypot(tx, tz);
  if (!(length > 0)) return { x: 0, z: 0 };
  return { x: -tz / length, z: tx / length };
}

function toSegmentFrame(arc, segment) {
  const routeLength = segment.routeLengthM;
  const mid = (segment.retailArcStart + segment.retailArcEnd) / 2;
  let value = arc;
  while (value < mid - routeLength / 2) value += routeLength;
  while (value > mid + routeLength / 2) value -= routeLength;
  return value;
}

function interpolateSegment(segment, retailArc) {
  const points = segment.points;
  const value = toSegmentFrame(retailArc, segment);
  if (value < segment.retailArcStart - 1e-9 || value > segment.retailArcEnd + 1e-9) {
    return null;
  }
  if (value <= points[0][1]) {
    return { measuredArc: points[0][0], residualM: points[0][2] };
  }
  const last = points[points.length - 1];
  if (value >= last[1]) {
    return { measuredArc: last[0], residualM: last[2] };
  }
  let low = 0;
  let high = points.length - 1;
  while (high - low > 1) {
    const mid = (low + high) >> 1;
    if (points[mid][1] <= value) low = mid;
    else high = mid;
  }
  const a = points[low];
  const b = points[high];
  const span = b[1] - a[1];
  const t = span > 0 ? (value - a[1]) / span : 0;
  return {
    measuredArc: a[0] + (b[0] - a[0]) * t,
    residualM: a[2] + (b[2] - a[2]) * t
  };
}

function findSegment(segments, routeIndex, retailArc) {
  for (const segment of segments) {
    if (segment.routeIndex !== routeIndex) continue;
    const hit = interpolateSegment(segment, retailArc);
    if (hit !== null) return { segment, ...hit };
  }
  return null;
}

/**
 * The correspondence is tied to the exact measured layout it was built from.
 * Returns null when the layout is the committed one, otherwise a reason.
 */
function layoutIssue(map, layout) {
  const samples = layout?.course?.samples;
  if (!Array.isArray(samples) || samples.length === 0) {
    return 'no-measured-sample: layout.course.samples is empty';
  }
  const expected = map.measuredLayout;
  const length = measuredLengthOf(layout);
  if (!Number.isFinite(length) || Math.abs(length - expected.lengthMetres) > 1e-6) {
    return 'layout-mismatch: course.lengthMetres ' + length +
      ' m != committed ' + expected.lengthMetres + ' m';
  }
  if (samples.length !== expected.sampleCount) {
    return 'layout-mismatch: sample count ' + samples.length +
      ' != committed ' + expected.sampleCount;
  }
  const first = samples[0];
  const last = samples[samples.length - 1];
  if (Math.abs((first.x ?? 0) - expected.firstSample.x) > 1e-6 ||
      Math.abs((first.z ?? 0) - expected.firstSample.z) > 1e-6 ||
      Math.abs((last.x ?? 0) - expected.lastSample.x) > 1e-6 ||
      Math.abs((last.z ?? 0) - expected.lastSample.z) > 1e-6) {
    return 'layout-mismatch: first/last sample differ from the committed measured layout';
  }
  return null;
}

export const ARC_CORRESPONDENCE = deepFreeze(/*__ARC_CORRESPONDENCE__*/);

export const PHYSICAL_PLACEMENT_DATA = deepFreeze(/*__PHYSICAL_PLACEMENT_DATA__*/);

/**
 * Place the retail pickups of a map at their retail arc mapped through the
 * committed measured-arc <-> retail-arc correspondence table.
 *
 * @param {'amboy'|'gracia'|'river'} mapId
 * @param {{course:{lengthMetres:number,band?:{halfWidthMetres:number},
 *   corridor?:{halfWidthMetres:number},samples:Array<{arc:number,x:number,z:number,groundY?:number}>}}} layout
 * @returns {{schema:string, mapId:string, source:string, physicalProjection:boolean,
 *   pickups:Array<object>, unsupported:Array<{id:string,uid:number,type:string,reason:string}>}}
 */
export function physicalPlacementsFor(mapId, layout) {
  const map = PHYSICAL_PLACEMENT_DATA.maps[mapId];
  if (!map) {
    fail('unknown map ' + JSON.stringify(mapId) + ' (use ' +
      Object.keys(PHYSICAL_PLACEMENT_DATA.maps).join(', ') + ')');
  }
  const correspondenceMap = ARC_CORRESPONDENCE.maps[mapId];
  if (!correspondenceMap) {
    fail('arc correspondence has no map ' + JSON.stringify(mapId));
  }
  const segments = correspondenceMap.segments;
  const samples = layout?.course?.samples;
  const band = bandOf(layout);
  const issue = layoutIssue(map, layout);
  const layoutId = layout?.courseId ?? layout?.course?.name ?? map.measuredLayout.id;
  const pickups = [];
  const unsupported = [];

  for (const row of map.rows) {
    const id = mapId + ':' + row.uid;
    if (issue !== null) {
      unsupported.push({ id, uid: row.uid, type: row.type, reason: issue });
      continue;
    }
    if (!band) {
      fail('layout has neither course.band.halfWidthMetres nor ' +
        'course.corridor.halfWidthMetres; the retail lateral cannot be clamped');
    }
    const hit = findSegment(segments, row.routeIndex, row.arc);
    if (hit === null) {
      const routeSegments = segments.filter((segment) => segment.routeIndex === row.routeIndex);
      const reason = routeSegments.length === 0
        ? 'no-measured-correspondence: route ' + row.route + ' (index ' +
          row.routeIndex + ') has no measured-arc correspondence segment; the measured ' +
          'layout is not on this retail racing line within the ' +
          ARC_CORRESPONDENCE.gateMetres.toFixed(3) + ' m gate'
        : 'no-measured-correspondence: retail arc ' + row.arc.toFixed(6) +
          ' m on route ' + row.route + ' (index ' + row.routeIndex +
          ') is outside the measured-arc correspondence [' +
          routeSegments.map((segment) =>
            segment.retailArcStart.toFixed(3) + '..' + segment.retailArcEnd.toFixed(3)).join(', ') +
          '] m';
      unsupported.push({ id, uid: row.uid, type: row.type, reason });
      continue;
    }

    const sampleHit = nearestSample(samples, hit.measuredArc);
    const normal = leftNormalAt(samples, sampleHit.index);
    const retailLateral = row.lateral;
    const clamped = Math.abs(retailLateral) > band.halfWidthMetres;
    const appliedLateral = clamped
      ? Math.sign(retailLateral) * band.halfWidthMetres
      : retailLateral;
    const sampleArc = sampleHit.sample.arc ?? hit.measuredArc;
    const x = (sampleHit.sample.x ?? 0) + normal.x * appliedLateral;
    const z = (sampleHit.sample.z ?? 0) + normal.z * appliedLateral;
    const y = sampleHit.sample.groundY ?? sampleHit.sample.height ?? 0;

    pickups.push({
      id,
      uid: row.uid,
      type: row.type,
      x: round6(x),
      y: round6(y),
      z: round6(z),
      arc: round6(sampleArc),
      measuredArc: round6(sampleArc),
      retailArc: round6(row.arc),
      routeLengthM: round6(row.routeLengthM),
      lateral: round6(appliedLateral),
      retailLateral: round6(retailLateral),
      clamped,
      clampedBy: round6(Math.max(0, Math.abs(retailLateral) - band.halfWidthMetres)),
      route: row.route,
      routeIndex: row.routeIndex,
      segmentId: hit.segment.id,
      mappingResidualM: round6(hit.residualM),
      sampleIndex: sampleHit.index,
      physicalProjection: true,
      source: 'retail uid ' + row.uid + ' route ' + row.route +
        ' (index ' + row.routeIndex + ') retail arc ' + row.arc.toFixed(6) + ' m' +
        ' -> correspondence ' + hit.segment.id + ' residual ' + hit.residualM.toFixed(6) +
        ' m -> measured ' + layoutId + ' arc ' + sampleArc.toFixed(6) +
        ' m (sample ' + sampleHit.index + ' of ' + samples.length + ')' +
        '; lateral ' + retailLateral.toFixed(6) + ' m ' +
        (clamped ? 'clamped to ' + appliedLateral.toFixed(6) : 'kept') +
        ' (band +/-' + band.halfWidthMetres.toFixed(6) + ' m from ' + band.source + ')' +
        '; rule retail-arc-correspondence + banded-lateral; physicalProjection true'
    });
  }

  return {
    schema: PHYSICAL_PLACEMENT_SCHEMA,
    mapId,
    physicalProjection: true,
    source: 'physically-corresponded retail pickup placement for ' + mapId +
      ' on measured layout ' + layoutId +
      ' (' + (measuredLengthOf(layout) ?? 0).toFixed(6) + ' m, band +/-' +
      (band ? band.halfWidthMetres.toFixed(6) : 'n/a') + ' m); ' +
      'rule retail-arc-correspondence + banded-lateral; ' +
      'correspondence ' + map.correspondence.segmentCount + ' segment(s) from ' +
      map.correspondence.path + ' (gate ' + map.correspondence.gateMetres.toFixed(3) +
      ' m); retail routes from probes/powerups/data/pickup-routes.json',
    pickups,
    unsupported
  };
}
